namespace sv_446076090969436b9b024a6c296b8a6c.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            OnChanged?.Invoke();
        }
    }

    // Predefined warehouses for the dropdown
    public static IReadOnlyList<(string Id, string Name)> Warehouses { get; } =
    [
        ("WH-001", "Warehouse A — Main Distribution"),
        ("WH-002", "Warehouse B — East Regional"),
        ("WH-003", "Warehouse C — West Regional"),
        ("WH-004", "Warehouse D — Cold Storage"),
    ];

    /// <summary>
    /// Raised when the selected warehouse changes.
    /// Components should call InvokeAsync(StateHasChanged) in their handler.
    /// </summary>
    public event Action? OnChanged;
}

namespace sv_446076090969436b9b024a6c296b8a6c.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private Timer? _timer;
    private int _subscriberCount;
    private readonly Lock _lock = new();
    private readonly Random _random = new();

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Raised when new alert data arrives. All subscribed components should refresh.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChanged += HandleWarehouseChanged;
    }

    /// <summary>Simulates a database query for low-stock items.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants polling to be active.
    /// Polling starts on the first subscriber and stops when all unsubscribe.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
            }
        }
    }

    /// <summary>Call when a component no longer needs polling.</summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _timer?.Dispose();
                _timer = null;
            }
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        LatestLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately re-poll when the warehouse changes
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        LatestLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    public void Dispose()
    {
        _warehouseState.OnChanged -= HandleWarehouseChanged;
        _timer?.Dispose();
    }
}

