@rendermode InteractiveServer
@using sv_446076090969436b9b024a6c296b8a6c.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged" style="max-width: 280px;">
    @foreach (var wh in WarehouseStateService.Warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-001";
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChanged += HandleStateChanged;
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChanged -= HandleStateChanged;
    }
}

